function biggestToTheRight(nums: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    let best = -1;
    for (let j = i + 1; j < nums.length; j++) best = Math.max(best, nums[j]);
    out.push(best);
  }
  return out;
}

