function biggestToTheRight(nums: number[]): number[] {
  const out = new Array<number>(nums.length);
  let best = -1;
  for (let i = nums.length - 1; i >= 0; i--) {
    out[i] = best; // before nums[i] joins the running maximum
    best = Math.max(best, nums[i]);
  }
  return out;
}

